// План specs/job-payments.md 1.4 (кейс .qa/tests/job-payments/JP-04). Pre-Prod, preprod-ttp (TTP Test Locks), десктоп Chrome, EN.
// @writes @data: работа «QA-AUTO pay link … #67b4b4» ($5) + ссылка на оплату $5.00. Оплаты нет; Text / Email не нажимаются
// (запросы send-sms/send-email обрываются). Очистка в finally: Cancel link, работа → Cancelled.
import { test, expect } from '../../fixtures';
import {
  PREPROD, REMAINING, amountRe, blockMessaging, cancelJob, cancelOpenLinks, createJobWithBalance, methodButton,
  openPaymentsTab, openTakeAPayment,
} from './payments-helpers';

test.describe('Job → Payments: Payment Link (#67b4b4)', () => {
  test('QA-AUTO: Payment Link → Create link shows Link ready with Copy; link points to the current environment #67b4b4 @desktop @writes @data', async ({ asUser }) => {
    test.setTimeout(180_000);
    const page = await asUser('preprod-ttp');
    await page.context().grantPermissions(['clipboard-read', 'clipboard-write'], { origin: PREPROD });
    const messaging = await blockMessaging(page);
    let jobUrl: string | null = null;
    try {
      jobUrl = await createJobWithBalance(page, 'link');
      await openPaymentsTab(page, jobUrl);

      // Шаг 1: Remaining to pay → Payment Link → Create link
      const choose = await openTakeAPayment(page);
      await methodButton(choose, 'Payment Link').click();
      const dialog = page.getByRole('dialog').filter({ hasText: /Payment link/i }).last();
      await expect(dialog).toBeVisible();
      await dialog.getByRole('button', { name: /^Create link$/i }).click();

      // «Link ready…» + поле со ссылкой (комментарий 05.11; «מה רצוי» п.2)
      await expect(dialog.getByText('Link ready. Send it to the customer:')).toBeVisible({ timeout: 30_000 });
      const linkInput = dialog.getByRole('textbox').first();
      await expect(linkInput).toHaveValue(new RegExp(`^${PREPROD.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}/`));
      const link = await linkInput.inputValue();
      expect(link, 'ссылка не на prod').not.toContain('app.techory.ai');

      // Шаг 2: Copy → Copied, в буфере — та же ссылка
      await dialog.getByRole('button', { name: /^Copy$/ }).click();
      await expect(dialog.getByRole('button', { name: /Copied/ })).toBeVisible();
      expect(await page.evaluate(() => navigator.clipboard.readText()), 'буфер обмена').toBe(link);

      // Done → ссылка на сумму остатка в «Payment links» с Copy link / Cancel link
      await dialog.getByRole('button', { name: /^Done$/ }).click();
      await expect(dialog).toBeHidden();
      const main = page.getByRole('main');
      await expect(main.getByText('Payment links', { exact: true })).toBeVisible();
      const row = main.locator('div, li, tr')
        .filter({ has: page.getByText(amountRe(REMAINING)) })
        .filter({ has: page.getByRole('button', { name: /Cancel link/i }) })
        .last();
      await expect(row).toBeVisible();
      await expect(row.getByRole('button', { name: /Copy link/i })).toBeVisible();
      await expect(row).not.toContainText('Paid');

      expect(messaging, 'запросов отправки SMS/email быть не должно').toEqual([]);
    } finally {
      await cancelOpenLinks(page, jobUrl);
      await cancelJob(page, jobUrl);
    }
  });
});
